INSERT INTO `tourist_attractions` (`id`, `region_id`, `division_id`, `category`, `subtype`, `name`, `summary`, `road_address`, `parcel_address`, `latitude`, `longitude`, `phone`, `website_url`, `venue`, `start_date`, `end_date`, `start_time`, `end_time`, `fee_info`, `parking_info`, `organizer`, `managing_agency`, `rating`, `review_count`, `source_id`, `source_record_key`, `source_updated_date`, `details_json`, `created_at`) VALUES
(1, 4, 61, '관광지', '관광지', '대신주말농장 정보화마을', '섬진강 자연분지 양지바른 곳에 자리한 대신주말농장마을섬진강변의 기름지고 넓은 평지에 맑은 물과 깨끗한 공기를 간직한 자연그대로의 환경을 보존한 마을로 환경농업을 실천하고 미래를 준비하는 농촌체험형 녹색의 전원마을이다.300여 농가가 옹기종기 모여 사는 이곳은 곡성읍 대평리 1,2,3구와 신리 4개의 행정마을로 구성되어 있으며 대평리와 신리의 첫 자를 따 대신주말농장마을이라 하였다.주민 70이상이 시설하우스에서 지역의 특산물인 딸기, 멜론, 화훼를 생산하고 있으며 우수한 맛이 인정되어 딸기와 메론, 화훼를 일본등 외국에 수출하고 있다.대신주말농장마을 주변은 전라선 철도, 호남고속도로, 국도 4개 노선이 지나고 광주, 순천, 남원과 인접한 편리한 교통지역으로 증기기관차와 레일바이크 체험, 음악분수, 1004장미공원, 놀이공간을 갖춘 섬진강기차마을이 인접하고 있어 갖가지 체험관광을 즐길수 있다.', '전남광주통합특별시 곡성군 곡성읍 신리길 24-1', '전남광주통합특별시 곡성군 곡성읍 신리 324-2', 35.29488111, 127.3237142, '061-363-2011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '85aabcc87c792605c090412815e7538c11f7d2be290901c9bdf5e381b9143943', '2026-08-08', '{"관광지명": "대신주말농장 정보화마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 곡성읍 신리길 24-1", "소재지지번주소": "전남광주통합특별시 곡성군 곡성읍 신리 324-2", "위도": "35.29488111", "경도": "127.3237142", "면적": "285", "공공편익시설정보": "주차장", "지정일자": "2021-09-01", "수용인원수": "300", "주차가능수": "5", "관광지소개": "섬진강 자연분지 양지바른 곳에 자리한 대신주말농장마을섬진강변의 기름지고 넓은 평지에 맑은 물과 깨끗한 공기를 간직한 자연그대로의 환경을 보존한 마을로 환경농업을 실천하고 미래를 준비하는 농촌체험형 녹색의 전원마을이다.300여 농가가 옹기종기 모여 사는 이곳은 곡성읍 대평리 1,2,3구와 신리 4개의 행정마을로 구성되어 있으며 대평리와 신리의 첫 자를 따 대신주말농장마을이라 하였다.주민 70이상이 시설하우스에서 지역의 특산물인 딸기, 멜론, 화훼를 생산하고 있으며 우수한 맛이 인정되어 딸기와 메론, 화훼를 일본등 외국에 수출하고 있다.대신주말농장마을 주변은 전라선 철도, 호남고속도로, 국도 4개 노선이 지나고 광주, 순천, 남원과 인접한 편리한 교통지역으로 증기기관차와 레일바이크 체험, 음악분수, 1004장미공원, 놀이공간을 갖춘 섬진강기차마을이 인접하고 있어 갖가지 체험관광을 즐길수 있다.", "관리기관전화번호": "061-363-2011", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(2, 4, 61, '관광지', '관광지', '봉정 농촌체험 휴양마을', '‘봉정마을’은 날던 봉황이 보금자리에 들어 알을 품은 모습같아하여 봉정(鳳停)이라고 불렸습니다.쌀엿의 향기가 가득한 마을 안쪽으로는 두 팔을 벌려도 안을 수 없는 느티나무와 선인들의 배움에 대한 열정이 남아 있는 영류재가 있고, 뒤쪽에는 넓은 논밭과 저수지 위로 이어진 아름다운 편백나무 산책로가 있습니다.다양한 체험과 함께하는 최고의 힐링 깨끗한 자연 환경 속의 농산물을 만날 수 있는 봉정농촌체험휴양마을로 오세요', '전남광주통합특별시 곡성군 죽곡면 봉정길 43-137', '전남광주통합특별시 곡성군 죽곡면 봉정리 815', 35.19394727, 127.3107811, '061-363-2011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'd3f464e97dca5f01af044518056fe0f5a51c6af63d728ad1ac360ba6597606fa', '2026-08-08', '{"관광지명": "봉정 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 죽곡면 봉정길 43-137", "소재지지번주소": "전남광주통합특별시 곡성군 죽곡면 봉정리 815", "위도": "35.19394727", "경도": "127.3107811", "면적": "1015", "공공편익시설정보": "무선 인터넷+화장실", "지정일자": "2021-09-01", "수용인원수": "30", "주차가능수": "0", "관광지소개": "‘봉정마을’은 날던 봉황이 보금자리에 들어 알을 품은 모습같아하여 봉정(鳳停)이라고 불렸습니다.쌀엿의 향기가 가득한 마을 안쪽으로는 두 팔을 벌려도 안을 수 없는 느티나무와 선인들의 배움에 대한 열정이 남아 있는 영류재가 있고, 뒤쪽에는 넓은 논밭과 저수지 위로 이어진 아름다운 편백나무 산책로가 있습니다.다양한 체험과 함께하는 최고의 힐링 깨끗한 자연 환경 속의 농산물을 만날 수 있는 봉정농촌체험휴양마을로 오세요", "관리기관전화번호": "061-363-2011", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(3, 4, 61, '관광지', '관광지', '칠봉 농촌체험 휴양마을', '곡성 겸면 칠봉마을은 옛 전통이 그대로 살아 있은 농촌 체험마을입니다.마을 뒤로는 일곱 봉우리기 평풍처럼 둘러 쌓여 있고 앞으로는 동계동천을 이루어 신선이 사는 곳으로써 마을 한복판에 체험마을이 자리 잡고 있습니다.철 따라 감자캐기,땅콩캐기.고구마캐기등 농사체험이 있고 감잎차,뽕잎차.연잎차 만들기 체험이 있으며 칠봉산 등산체험은 어린이,장년,노인들 모두 즐길수 있는 인기 체험이며 목화공원의 목화체험(목화따기,목화 꽃다발 만들기,무명실 뽑기등) 이 다른 고장과 차별화 되는 체험꺼리가 있습니다.또한 미풍양속을 지키는 마을로써 구정에 합동세배,삼월삼일 칠봉 큰샘제,추석절 윳놀이행사등 민속놀이 행사를 꾸준히 하고있는 마을 입니다.', '전남광주통합특별시 곡성군 겸면 칠봉길 89', '전남광주통합특별시 곡성군 겸면 칠봉리 311', 35.24620059, 127.1802226, '061-362-1049', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '5f6f4a6fc61bcd1365699a866cfc8c3ef74ebc7a36ff450552ed60a390dec486', '2026-08-08', '{"관광지명": "칠봉 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 겸면 칠봉길 89", "소재지지번주소": "전남광주통합특별시 곡성군 겸면 칠봉리 311", "위도": "35.24620059", "경도": "127.1802226", "면적": "253", "공공편익시설정보": "주차장+화장실", "지정일자": "2021-09-01", "수용인원수": "30", "주차가능수": "10", "관광지소개": "곡성 겸면 칠봉마을은 옛 전통이 그대로 살아 있은 농촌 체험마을입니다.마을 뒤로는 일곱 봉우리기 평풍처럼 둘러 쌓여 있고 앞으로는 동계동천을 이루어 신선이 사는 곳으로써 마을 한복판에 체험마을이 자리 잡고 있습니다.철 따라 감자캐기,땅콩캐기.고구마캐기등 농사체험이 있고 감잎차,뽕잎차.연잎차 만들기 체험이 있으며 칠봉산 등산체험은 어린이,장년,노인들 모두 즐길수 있는 인기 체험이며 목화공원의 목화체험(목화따기,목화 꽃다발 만들기,무명실 뽑기등) 이 다른 고장과 차별화 되는 체험꺼리가 있습니다.또한 미풍양속을 지키는 마을로써 구정에 합동세배,삼월삼일 칠봉 큰샘제,추석절 윳놀이행사등 민속놀이 행사를 꾸준히 하고있는 마을 입니다.", "관리기관전화번호": "061-362-1049", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(4, 4, 61, '관광지', '관광지', '용암 농촌체험 휴양마을', '곡성 용암마을은 목사동면에 위치한 농촌체험휴양마을입니다.계절별 팜놀이를 통해서 아이와 어른이 함께 즐길수 있는데 특히 여름에는 은어잡기체험을 진행하고 있습니다.', '전남광주통합특별시 곡성군 목사동면 용사용암길 8-2', '전남광주통합특별시 곡성군 목사동면 용사리 38', 35.12878212, 127.3134337, '061-362-0990', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '67f9c0392b2be5aa0a92604a7b3e825e42e84f1b152881e06fd3bf2fa8730e9e', '2026-08-08', '{"관광지명": "용암 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 목사동면 용사용암길 8-2", "소재지지번주소": "전남광주통합특별시 곡성군 목사동면 용사리 38", "위도": "35.12878212", "경도": "127.3134337", "면적": "641", "공공편익시설정보": "주차장", "지정일자": "2021-09-01", "수용인원수": "15", "주차가능수": "5", "관광지소개": "곡성 용암마을은 목사동면에 위치한 농촌체험휴양마을입니다.계절별 팜놀이를 통해서 아이와 어른이 함께 즐길수 있는데 특히 여름에는 은어잡기체험을 진행하고 있습니다.", "관리기관전화번호": "061-362-0990", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(5, 4, 61, '관광지', '관광지', '죽산 농촌체험 휴양마을', '곡성 죽산사과마을은 농촌체험휴양마을이다. 목화공원과 인접한 곳으로 시골의 향취를 마음껏 느낄 수 있다.죽산사과마을에서 체험할수 있는 프로그램들도 다양한데 그 중에서 먹거리체험으로는 인절미 떡메치기 체험있고. 계절에 따라 사과따기 감따기등 각종 수확체험이 있다.', '전남광주통합특별시 곡성군 겸면 죽산하늘재길42', '전남광주통합특별시 곡성군 겸면 운교리 468-13', 35.23352336, 127.1752282, '061-363-2011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'c12ec635502c06ddf3d649840e28f9e77fb0563152f1b1faa12adb9693f761b7', '2026-08-08', '{"관광지명": "죽산 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 겸면 죽산하늘재길42", "소재지지번주소": "전남광주통합특별시 곡성군 겸면 운교리 468-13", "위도": "35.23352336", "경도": "127.1752282", "면적": "765", "공공편익시설정보": "화장실", "지정일자": "2021-09-01", "수용인원수": "1000", "주차가능수": "0", "관광지소개": "곡성 죽산사과마을은 농촌체험휴양마을이다. 목화공원과 인접한 곳으로 시골의 향취를 마음껏 느낄 수 있다.죽산사과마을에서 체험할수 있는 프로그램들도 다양한데 그 중에서 먹거리체험으로는 인절미 떡메치기 체험있고. 계절에 따라 사과따기 감따기등 각종 수확체험이 있다.", "관리기관전화번호": "061-363-2011", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(6, 4, 61, '관광지', '관광지', '가정 농촌체험 휴양마을', '곡성 가정마을은 녹색농촌체험마을이다. 청소년 야영장과 인접해 있고, 섬진강과 시골의 향취를 마음껏 느낄 수 있다. 가정마을에서 체험할수 있는 프로그램들도 다양한데 그 중에서 먹거리체험으로는 인절미 떡메치기와 전통 손두부,콩비지도넛 만들기 체험이다. 계절에 따라 고사리꺾기,매실따기,복숭아따기,자두,살구,감,배등 각종 수확체험이 단연 인기체험이다', '전남광주통합특별시 곡성군 고달면 가정마을길 65', '전남광주통합특별시 곡성군 고달면 두가리 630-3', 35.22727591, 127.3704119, '061-363-1637', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '4', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '2d729527dec2d0d4eec1122314efb3f8979fecdd6d049e6e756e3da30d4c8cca', '2026-08-08', '{"관광지명": "가정 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 고달면 가정마을길 65", "소재지지번주소": "전남광주통합특별시 곡성군 고달면 두가리 630-3", "위도": "35.22727591", "경도": "127.3704119", "면적": "658", "공공편익시설정보": "주차장+운동기구", "지정일자": "2021-09-01", "수용인원수": "110", "주차가능수": "4", "관광지소개": "곡성 가정마을은 녹색농촌체험마을이다. 청소년 야영장과 인접해 있고, 섬진강과 시골의 향취를 마음껏 느낄 수 있다. 가정마을에서 체험할수 있는 프로그램들도 다양한데 그 중에서 먹거리체험으로는 인절미 떡메치기와 전통 손두부,콩비지도넛 만들기 체험이다. 계절에 따라 고사리꺾기,매실따기,복숭아따기,자두,살구,감,배등 각종 수확체험이 단연 인기체험이다", "관리기관전화번호": "061-363-1637", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(7, 4, 61, '관광지', '관광지', '안개 농촌체험 휴양마을', '‘곡성안개마을’은 곡성군 고달면 목동리 연꽃방죽 옆에 위치하고 있으며 국가보호습지로 지정된 섬진강 ‘침실습지’를 바라보는 장소에 위치한 체험휴양마을입니다.아침이면 강변 습지에 물안개가 피어오르고 강변을 따라 이어지는 섬진강 자전거길의 풍경은 오염되지 않은 청정자연 그대로의 강의 모습을 고스란히 간직하고 있으며 강 건너 기차마을의 증기기관차의 기적소리가 향수를 불러일으키는 곳입니다.', '전남광주통합특별시 곡성군 고달면 고산로 39-18', '전남광주통합특별시 곡성군 고달면 목동리 258-5', 35.29052093, 127.3419816, '061-363-3231', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '5209595ff9e36e0dd8329efda73874f7fb747aa26e65dedfe168b9b3067d6675', '2026-08-08', '{"관광지명": "안개 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 고달면 고산로 39-18", "소재지지번주소": "전남광주통합특별시 곡성군 고달면 목동리 258-5", "위도": "35.29052093", "경도": "127.3419816", "면적": "2360", "공공편익시설정보": "주차장", "지정일자": "2021-09-01", "수용인원수": "200", "주차가능수": "10", "관광지소개": "‘곡성안개마을’은 곡성군 고달면 목동리 연꽃방죽 옆에 위치하고 있으며 국가보호습지로 지정된 섬진강 ‘침실습지’를 바라보는 장소에 위치한 체험휴양마을입니다.아침이면 강변 습지에 물안개가 피어오르고 강변을 따라 이어지는 섬진강 자전거길의 풍경은 오염되지 않은 청정자연 그대로의 강의 모습을 고스란히 간직하고 있으며 강 건너 기차마을의 증기기관차의 기적소리가 향수를 불러일으키는 곳입니다.", "관리기관전화번호": "061-363-3231", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(8, 4, 61, '관광지', '관광지', '무창 농촌체험 휴양마을', '무창마을은 전남 곡성군의 북서쪽에 위치한 전형적인 시골마을입니다.200여 농가가 모여있는 마을로 호남고속도로가 지나고 옥과 IC과 있어 광주와 인접해 교통이 편리한 농촌마을입니다.섬진강의 맑은 물과 깨끗한 공기와 더불어 점토질 량이 높아 기름지고 넓은 황등들을 중심으로 황등쌀과 사과.포도.송화버섯 수확체험이 가능한 체험마을입니다.', '전남광주통합특별시 곡성군 옥과면 금의길 59', '전남광주통합특별시 곡성군 옥과면 무창리 1164-16', 35.28642041, 127.1520961, '061-363-2011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '66b830aca159f889fadd529aa1b8a4794391603e9200d45e418080626cff20ba', '2026-08-08', '{"관광지명": "무창 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 옥과면 금의길 59", "소재지지번주소": "전남광주통합특별시 곡성군 옥과면 무창리 1164-16", "위도": "35.28642041", "경도": "127.1520961", "면적": "653", "공공편익시설정보": "화장실+주차장", "지정일자": "2021-09-01", "수용인원수": "50", "주차가능수": "7", "관광지소개": "무창마을은 전남 곡성군의 북서쪽에 위치한 전형적인 시골마을입니다.200여 농가가 모여있는 마을로 호남고속도로가 지나고 옥과 IC과 있어 광주와 인접해 교통이 편리한 농촌마을입니다.섬진강의 맑은 물과 깨끗한 공기와 더불어 점토질 량이 높아 기름지고 넓은 황등들을 중심으로 황등쌀과 사과.포도.송화버섯 수확체험이 가능한 체험마을입니다.", "관리기관전화번호": "061-363-2011", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(9, 4, 61, '관광지', '관광지', '상한 농촌체험 휴양마을', '하늘처럼 깨끗한 산골마을인 하늘나리마을은 천혜자원인 해발 753고지 봉두산 아래에 위치하여 작은 골짜기를 사이로 맑은 물이 흐르고 골짜기를 따라 등산로가 있습니다.깊은 산속에는 고로쇠나무가 자생하여 이른 봄이면 고로쇠 수액을 채취하고 또한 집집마다 시골민박을 운영하고 있는 정겨운 산골마을입니다.마을에서 채취한 갖가지 산나물과 버섯을 활용한 시골밥상은 정겨운 시골의 옛맛을 그대로 느낄수 있으며, 마을주민 전체가 공동체를 이뤄 체험마을 활동에 참여하고 있습니다.', '전남광주통합특별시 곡성군 죽곡면 상한길 240', '전남광주통합특별시 곡성군 죽곡면 하한리 672-4', 35.16105726, 127.3987916, '061-363-8546', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'abe160a396f76d0bba15cd55989b3b2e1e101fa7029813c2887c7a26dab421d9', '2026-08-08', '{"관광지명": "상한 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 죽곡면 상한길 240", "소재지지번주소": "전남광주통합특별시 곡성군 죽곡면 하한리 672-4", "위도": "35.16105726", "경도": "127.3987916", "면적": "1309", "공공편익시설정보": "주차장", "지정일자": "2021-09-01", "수용인원수": "100", "주차가능수": "5", "관광지소개": "하늘처럼 깨끗한 산골마을인 하늘나리마을은 천혜자원인 해발 753고지 봉두산 아래에 위치하여 작은 골짜기를 사이로 맑은 물이 흐르고 골짜기를 따라 등산로가 있습니다.깊은 산속에는 고로쇠나무가 자생하여 이른 봄이면 고로쇠 수액을 채취하고 또한 집집마다 시골민박을 운영하고 있는 정겨운 산골마을입니다.마을에서 채취한 갖가지 산나물과 버섯을 활용한 시골밥상은 정겨운 시골의 옛맛을 그대로 느낄수 있으며, 마을주민 전체가 공동체를 이뤄 체험마을 활동에 참여하고 있습니다.", "관리기관전화번호": "061-363-8546", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(10, 4, 61, '관광지', '관광지', '봉조 농촌체험 휴양마을', '즐겁고 보람있는 체험 활동이 가득한 봉조농촌체험학교섬진강의 맑은 기운과 지리산 따뜻한 숨결을 품은 산골 마을 봉조리 입구에는 오랜 시간동안 마을과 함께 한 작은 시골 초등학교가 있습니다.도시로 아이들이 떠나면서 비록 그 초등학교는 폐교가 되었지만, 이제 그 시골 학교는 봉조 마을 어르신들이 농촌 선생님이 되어 우리 아이들에게 시골의 넉넉함과 농촌의 풋풋한 생기를 함께 나누는 <봉조농촌체험학교>로 다시 태어났습니다.마을 주민들이 정성을 다해 관리하고 있는 아름다운 ‘봉조농촌체험학교’를 중심으로, 봉조리의 논과 밭에서 다양한 농촌 체험 활동을 비롯한 창의 체험 활동들을 초, 중, 고 학생과 함께 하고 있습니다.마음이 따뜻한 사람들의 마을 ‘봉조리’가 여러분을 두 팔 벌려 환영합니다', '전남광주통합특별시 곡성군 오곡면 봉조길 114', '전남광주통합특별시 곡성군 오곡면 봉조리 15-1', 35.21496518, 127.3604656, '061-362-5268', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'd6027b37bda139fab34d1223394e9d3af0b83a6c5b6d22f3e40ae4d737c4f7af', '2026-08-08', '{"관광지명": "봉조 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 오곡면 봉조길 114", "소재지지번주소": "전남광주통합특별시 곡성군 오곡면 봉조리 15-1", "위도": "35.21496518", "경도": "127.3604656", "면적": "2934", "공공편익시설정보": "주차장+화장실+개수대", "지정일자": "2021-09-01", "수용인원수": "180", "주차가능수": "5", "관광지소개": "즐겁고 보람있는 체험 활동이 가득한 봉조농촌체험학교섬진강의 맑은 기운과 지리산 따뜻한 숨결을 품은 산골 마을 봉조리 입구에는 오랜 시간동안 마을과 함께 한 작은 시골 초등학교가 있습니다.도시로 아이들이 떠나면서 비록 그 초등학교는 폐교가 되었지만, 이제 그 시골 학교는 봉조 마을 어르신들이 농촌 선생님이 되어 우리 아이들에게 시골의 넉넉함과 농촌의 풋풋한 생기를 함께 나누는 <봉조농촌체험학교>로 다시 태어났습니다.마을 주민들이 정성을 다해 관리하고 있는 아름다운 ‘봉조농촌체험학교’를 중심으로, 봉조리의 논과 밭에서 다양한 농촌 체험 활동을 비롯한 창의 체험 활동들을 초, 중, 고 학생과 함께 하고 있습니다.마음이 따뜻한 사람들의 마을 ‘봉조리’가 여러분을 두 팔 벌려 환영합니다", "관리기관전화번호": "061-362-5268", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(11, 4, 61, '관광지', '관광지', '두계 농촌체험 휴양마을', '곡성 두계외갓집체험마을은 천마산에서 섬진강으로 8km에 이어지는 계곡이 있고, 외갓집 같은 포근함과 옛 정취가 물씬 풍기는 자연경관이 가득한 조용한 시골 마을입니다.곡성관광을 마치고 조용히 휴식과 휴양을 할 수 있는 한옥팬션이 준비되어 있으며 다양한 체험프로그램들이 있지만 연중 가능한 인절미 떡메치기와 시골두부만들기 체험이 있고 봄철에 식용 야생꽃을 이용하여 추억을 한 가득 담아갈 수 있는 토란화전만들기 체험이 있습니다. 그 밖에 단감따기, 고추따기 등 다양한 농사체험이 있습니다.', '전남광주통합특별시 곡성군 고달면 두계길 126', '전남광주통합특별시 곡성군 고달면 두가리 494-1', 35.24354627, 127.3790396, '061-363-2011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'e260bc2caabbefb5d6c71440c0abd0ab4a9691bacd6cfaff5da03378b7e95b7f', '2026-08-08', '{"관광지명": "두계 농촌체험 휴양마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 고달면 두계길 126", "소재지지번주소": "전남광주통합특별시 곡성군 고달면 두가리 494-1", "위도": "35.24354627", "경도": "127.3790396", "면적": "957", "공공편익시설정보": "주치장", "지정일자": "2021-09-01", "수용인원수": "50", "주차가능수": "5", "관광지소개": "곡성 두계외갓집체험마을은 천마산에서 섬진강으로 8km에 이어지는 계곡이 있고, 외갓집 같은 포근함과 옛 정취가 물씬 풍기는 자연경관이 가득한 조용한 시골 마을입니다.곡성관광을 마치고 조용히 휴식과 휴양을 할 수 있는 한옥팬션이 준비되어 있으며 다양한 체험프로그램들이 있지만 연중 가능한 인절미 떡메치기와 시골두부만들기 체험이 있고 봄철에 식용 야생꽃을 이용하여 추억을 한 가득 담아갈 수 있는 토란화전만들기 체험이 있습니다. 그 밖에 단감따기, 고추따기 등 다양한 농사체험이 있습니다.", "관리기관전화번호": "061-363-2011", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(12, 4, 61, '관광지', '관광지', '섬진강변 자전거하이킹', '천혜의 자연경관을 가진 섬진강과 보성강변의 아름다운 도로와 경치좋은 산길(임도)를 따라 달려볼 수 있는 코스입니다.에코레일(Eco-Rail)자전거 열차를 통해 전국의 동호인들이 찾고 있습니다.', '전남광주통합특별시 곡성군 오곡면 기차마을로 232', '전남광주통합특별시 곡성군 오곡면 오지리 770-5', 35.27753393, 127.3082912, '061-360-8419', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '16d8f78fb4cc5f890478c4510cf80dd12c9e669414461e622e2faa9aa8c21a7e', '2026-08-08', '{"관광지명": "섬진강변 자전거하이킹", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 오곡면 기차마을로 232", "소재지지번주소": "전남광주통합특별시 곡성군 오곡면 오지리 770-5", "위도": "35.27753393", "경도": "127.3082912", "면적": "113345", "공공편익시설정보": "주차장+화장실", "지정일자": "2021-09-01", "수용인원수": "1000", "주차가능수": "10", "관광지소개": "천혜의 자연경관을 가진 섬진강과 보성강변의 아름다운 도로와 경치좋은 산길(임도)를 따라 달려볼 수 있는 코스입니다.에코레일(Eco-Rail)자전거 열차를 통해 전국의 동호인들이 찾고 있습니다.", "관리기관전화번호": "061-360-8419", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(13, 4, 61, '관광지', '관광지', '섬진강변 철쭉길', '섬진강변따라 만개하는 불타는듯 화려한 철쭉의 향연을 차, 자전거, 도보 그리고 섬진강레일바이크로 즐길 수 있다.봄이 무르익는 4월에서 5월 무렵이 환상의 드라이브 코스인 섬진강 17번 국도가 가장 아름다운 시기다. 그 무렵 이 길을 벚꽃과 철쭉으로 그리고 연두색 신록으로 화려하게 치장한다.섬진강변 예전 철길을 따라 빼곡하게 늘어선 철쭉이 병풍처럼 늘어서 있어서 드라이브하기에 안성맞춤이다.벚꽃이 지면 철쭉의 계절이 된다 . 연두색 신록이 새얼굴로 치장한듯 모든게 새로운 계절에 짙은 빨란물감이라도 뿌려놓은듯한 강력한 철쭉이 섬진강변을 따라 모두를 반겨주듯 꽉찬 배열로 연호하고 있다.', '전남광주통합특별시 곡성군 오곡면 섬진강로 2068', '전남광주통합특별시 곡성군 오곡면 오지리 12-1', 35.26690786, 127.3325028, '061-360-8792', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '8aefc497d704aab17f3555bad31f44c8485f476b1377526ed5fc5b701811f403', '2026-08-08', '{"관광지명": "섬진강변 철쭉길", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 오곡면 섬진강로 2068", "소재지지번주소": "전남광주통합특별시 곡성군 오곡면 오지리 12-1", "위도": "35.26690786", "경도": "127.3325028", "면적": "1471", "공공편익시설정보": "없음", "지정일자": "2021-09-01", "수용인원수": "1000", "주차가능수": "0", "관광지소개": "섬진강변따라 만개하는 불타는듯 화려한 철쭉의 향연을 차, 자전거, 도보 그리고 섬진강레일바이크로 즐길 수 있다.봄이 무르익는 4월에서 5월 무렵이 환상의 드라이브 코스인 섬진강 17번 국도가 가장 아름다운 시기다. 그 무렵 이 길을 벚꽃과 철쭉으로 그리고 연두색 신록으로 화려하게 치장한다.섬진강변 예전 철길을 따라 빼곡하게 늘어선 철쭉이 병풍처럼 늘어서 있어서 드라이브하기에 안성맞춤이다.벚꽃이 지면 철쭉의 계절이 된다 . 연두색 신록이 새얼굴로 치장한듯 모든게 새로운 계절에 짙은 빨란물감이라도 뿌려놓은듯한 강력한 철쭉이 섬진강변을 따라 모두를 반겨주듯 꽉찬 배열로 연호하고 있다.", "관리기관전화번호": "061-360-8792", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(14, 4, 61, '관광지', '관광지', '대황강자연휴식공원', '석곡의 순 우리말 이름은 ’돌실’이다. 석곡주변 대황강에 멋진 바위들이 많아 유래된 이름이다. 석곡 소재지 인근 대황강 주변에 넓게 조성된 공원이 석곡 대황강 휴식공원 또는 돌실 대황강 휴식공원이다.특히 이곳에는 코스모스로 가득 채워져 있어 꽃이 피는 매년 9월말이면 코스모스 축제가 열리고, 광주, 순천 등 인근 도시에서 수많은 관광객들이 몰려와 공원과 강변을 가득채운 코스모스의 향연을 즐긴다.석곡의 돼지 숯불구이가 점점 유명해지면서, 이곳을 찾아오는 관광객들의 발걸음이 꾸준히 이어지고, 카누를 비롯한 수상 레포츠를 즐길 수 있는 시설도 잘 갖추어져 있다.대황강 휴식공원 산책로에서는 봄에는 벚꽃이 피고, 여름에는 백일홍이, 가을에는 코스모스가 핀다.', NULL, '전남광주통합특별시 곡성군 석곡면 석곡리 246-12', 35.12890532, 127.2559931, '061-360-7420', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '50', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'dc83516ff9f615de32f8974965f296b56b7fb2468ef3e72805952f54082a0b07', '2026-08-08', '{"관광지명": "대황강자연휴식공원", "관광지구분": "관광지", "소재지지번주소": "전남광주통합특별시 곡성군 석곡면 석곡리 246-12", "위도": "35.12890532", "경도": "127.2559931", "면적": "53388", "공공편익시설정보": "주차장+화장실", "지정일자": "2021-09-01", "수용인원수": "1000", "주차가능수": "50", "관광지소개": "석곡의 순 우리말 이름은 ’돌실’이다. 석곡주변 대황강에 멋진 바위들이 많아 유래된 이름이다. 석곡 소재지 인근 대황강 주변에 넓게 조성된 공원이 석곡 대황강 휴식공원 또는 돌실 대황강 휴식공원이다.특히 이곳에는 코스모스로 가득 채워져 있어 꽃이 피는 매년 9월말이면 코스모스 축제가 열리고, 광주, 순천 등 인근 도시에서 수많은 관광객들이 몰려와 공원과 강변을 가득채운 코스모스의 향연을 즐긴다.석곡의 돼지 숯불구이가 점점 유명해지면서, 이곳을 찾아오는 관광객들의 발걸음이 꾸준히 이어지고, 카누를 비롯한 수상 레포츠를 즐길 수 있는 시설도 잘 갖추어져 있다.대황강 휴식공원 산책로에서는 봄에는 벚꽃이 피고, 여름에는 백일홍이, 가을에는 코스모스가 핀다.", "관리기관전화번호": "061-360-7420", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(15, 4, 61, '관광지', '관광지', '반구정습지', '대황강을 굽어보는 언덕 위에 서있는 ‘반구정’ 이라는 정자이름을 따서 대황강 만곡부에 형성된 습원을 반구정 습지로 부른다.김감선생은 문무를 두루 겸비한 조선 인조 때의 명신이었다. 병자호란이 일어나 인조임금이 남한산성으로 피신하자 선생은 두 아들과 함께 의병을 조직하여, 임금을 구출하고 오랑케를 물리치기 위해서 그곳으로 진격하지만, 인조임금의 항복소식을 접하고 비탄에 젖어 고향 석곡으로 내려와 은거한다. 선생은 강 언덕에 올라, 이곳의 빼어난 경치를 감상하는 것을 즐겼다.시를 짓고 노래하며 세상에 초연한 삶을 추구하였다. 그리고 그곳에 작고 소담한 정자 반구정을 앉혔다고 전한다. 애초에 김감선생이 지은 반구정은 주춧만 남아있을 뿐이라서, 지금 정자는 최근에 지어진 것이다.이곳에 제방이 들어서고, 주암댐으로 물길이 막히면서 반구정 습지의 많은 부분이 농경지로 개간되었고, 김감 선생의 시심을 불러일으키던 아름다운 옛 모습은 많이 훼손되었지만 반구정 습지는 아직도 온갖 종류의 조류들이 날아들고 무수한 동식물이 서식하는 생태계의 보고다. 반구정 습지는 산책 데크가 잘 갖추어져 있어, 도보 혹은 자전거를 타고 둘러볼 수 있다.', NULL, '전남광주통합특별시 곡성군 석곡면 봉전리 34-1', 35.11550817, 127.2453298, '061-360-7410', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '50', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'a92abbe68c674dba6f0ea848ee25ca45005a4ff22002baff06de2339cb6c99c7', '2026-08-08', '{"관광지명": "반구정습지", "관광지구분": "관광지", "소재지지번주소": "전남광주통합특별시 곡성군 석곡면 봉전리 34-1", "위도": "35.11550817", "경도": "127.2453298", "면적": "87656", "공공편익시설정보": "주차장", "지정일자": "2021-09-01", "수용인원수": "1000", "주차가능수": "50", "관광지소개": "대황강을 굽어보는 언덕 위에 서있는 ‘반구정’ 이라는 정자이름을 따서 대황강 만곡부에 형성된 습원을 반구정 습지로 부른다.김감선생은 문무를 두루 겸비한 조선 인조 때의 명신이었다. 병자호란이 일어나 인조임금이 남한산성으로 피신하자 선생은 두 아들과 함께 의병을 조직하여, 임금을 구출하고 오랑케를 물리치기 위해서 그곳으로 진격하지만, 인조임금의 항복소식을 접하고 비탄에 젖어 고향 석곡으로 내려와 은거한다. 선생은 강 언덕에 올라, 이곳의 빼어난 경치를 감상하는 것을 즐겼다.시를 짓고 노래하며 세상에 초연한 삶을 추구하였다. 그리고 그곳에 작고 소담한 정자 반구정을 앉혔다고 전한다. 애초에 김감선생이 지은 반구정은 주춧만 남아있을 뿐이라서, 지금 정자는 최근에 지어진 것이다.이곳에 제방이 들어서고, 주암댐으로 물길이 막히면서 반구정 습지의 많은 부분이 농경지로 개간되었고, 김감 선생의 시심을 불러일으키던 아름다운 옛 모습은 많이 훼손되었지만 반구정 습지는 아직도 온갖 종류의 조류들이 날아들고 무수한 동식물이 서식하는 생태계의 보고다. 반구정 습지는 산책 데크가 잘 갖추어져 있어, 도보 혹은 자전거를 타고 둘러볼 수 있다.", "관리기관전화번호": "061-360-7410", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(16, 4, 61, '관광지', '관광지', '대황강 출렁다리', '대황강출렁다리는 대황강을 가로질러 죽곡면 태평리와 목사동면 구룡리를 연결하는 185m 길이의 인도교로 국내하천에 설치된 최장거리 다리이다.그동안 접근이 불편했던 강건너편 7km가량의 트레킹 코스가 출렁다리와 연결되면서 대황강의 빼어난 경관을 한 눈에 감상할 수 있고, 안전하면서도 사람이 지나가면 위아래로 30cm 가량 출렁이기 때문에 출렁다리를 건너는 스릴이 있어 이곳을 찾는 이들에게 즐거움을 안겨준다. 트레킹코스는 소나무숲길, 대나무 숲길, 삼나무숲길로 구성되어 있다.', NULL, '전남광주통합특별시 곡성군 죽곡면 태평리 783', 35.15035107, 127.3286414, '061-360-8431', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'c833e1114b05b5fc6cc0ca2ea02654ccf0b221568e8d235fb312190b9fc9ed92', '2026-08-08', '{"관광지명": "대황강 출렁다리", "관광지구분": "관광지", "소재지지번주소": "전남광주통합특별시 곡성군 죽곡면 태평리 783", "위도": "35.15035107", "경도": "127.3286414", "면적": "608", "공공편익시설정보": "주차장", "지정일자": "2016-11-01", "수용인원수": "50", "주차가능수": "10", "관광지소개": "대황강출렁다리는 대황강을 가로질러 죽곡면 태평리와 목사동면 구룡리를 연결하는 185m 길이의 인도교로 국내하천에 설치된 최장거리 다리이다.그동안 접근이 불편했던 강건너편 7km가량의 트레킹 코스가 출렁다리와 연결되면서 대황강의 빼어난 경관을 한 눈에 감상할 수 있고, 안전하면서도 사람이 지나가면 위아래로 30cm 가량 출렁이기 때문에 출렁다리를 건너는 스릴이 있어 이곳을 찾는 이들에게 즐거움을 안겨준다. 트레킹코스는 소나무숲길, 대나무 숲길, 삼나무숲길로 구성되어 있다.", "관리기관전화번호": "061-360-8431", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(17, 4, 61, '관광지', '관광지', '곡성집라인', '공중 비행의 스릴감과 천혜의 자연 경관으로 유명한 섬진강변의 수려한 경치가 주는 경이로움을 모두 느낄 수 있는 곡성 집라인입니다.', '전남광주통합특별시 곡성군 오곡면 섬진강로 1492', '전남광주통합특별시 곡성군 오곡면 송정리 60-2', 35.23192974, 127.3698908, '061-362-0494', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'a17a84a7d19d8f7a067f8c00e18264113d2b976be3a17436417d5a2320ce5ca8', '2026-08-08', '{"관광지명": "곡성집라인", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 오곡면 섬진강로 1492", "소재지지번주소": "전남광주통합특별시 곡성군 오곡면 송정리 60-2", "위도": "35.23192974", "경도": "127.3698908", "면적": "686", "공공편익시설정보": "주차장", "지정일자": "2018-10-01", "수용인원수": "20", "주차가능수": "5", "관광지소개": "공중 비행의 스릴감과 천혜의 자연 경관으로 유명한 섬진강변의 수려한 경치가 주는 경이로움을 모두 느낄 수 있는 곡성 집라인입니다.", "관리기관전화번호": "061-362-0494", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(18, 4, 61, '관광지', '관광지', '섬진강 레일바이크', '아름다운 섬진강을 품고 내려가는 색다른 경험을 온 가족이 함께 즐길수 있는 섬진강레일바이크는 구 전라선 철도를 이용하여 섬진강변을 따라 운행하고 있다. 2인승과 4인승이 있으며 섬진강과 국도 17호선을 따라 운행하며 아름다운 청정자연을 만끽할 수 있다.', '전남광주통합특별시 곡성군 오곡면 섬진강로 1465 (가정역)', '전남광주통합특별시 곡성군 오곡면 송정리 55-4', 35.23015492, 127.3682034, '061-362-7717', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '210', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '8cec8cf5d00e24494aa6574ce3a3cfcf7da9c68c5cee4dd151559e8d1996099e', '2026-08-08', '{"관광지명": "섬진강 레일바이크", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 오곡면 섬진강로 1465 (가정역)", "소재지지번주소": "전남광주통합특별시 곡성군 오곡면 송정리 55-4", "위도": "35.23015492", "경도": "127.3682034", "면적": "372", "공공편익시설정보": "주차장", "지정일자": "2008-06-01", "수용인원수": "240", "주차가능수": "210", "관광지소개": "아름다운 섬진강을 품고 내려가는 색다른 경험을 온 가족이 함께 즐길수 있는 섬진강레일바이크는 구 전라선 철도를 이용하여 섬진강변을 따라 운행하고 있다. 2인승과 4인승이 있으며 섬진강과 국도 17호선을 따라 운행하며 아름다운 청정자연을 만끽할 수 있다.", "관리기관전화번호": "061-362-7717", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(19, 4, 61, '관광지', '관광지', '곡성기차마을 패러글라이딩체험', '섬진강 기찻길따라 떠나는 하늘여행 내안의 버킷리스트를 오늘 완성하세요세계대회를 개최할 수 있는 규모의 전국 최대의 패러글라이딩 체험장입니다.남녀노소 누구나 스릴 넘치는 긴장과 재미로 평생 이야기 할 수 있는 재미만 가져가세요~고객님께서 원하시는 체험을 선택 하시기만 하면 아주 멋지고 스릴넘치는 내안의 버킷리스트와 함께 소중한 추억을 담아 드리겠습니다.', NULL, '전남광주통합특별시 곡성군 오곡면 덕산리 123-6', 35.26672854, 127.3087391, '061-363-6696', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '16406f01a86b8893a0f8321aebb1358b197d33e60cf8fd03efb216e561b3cdda', '2026-08-08', '{"관광지명": "곡성기차마을 패러글라이딩체험", "관광지구분": "관광지", "소재지지번주소": "전남광주통합특별시 곡성군 오곡면 덕산리 123-6", "위도": "35.26672854", "경도": "127.3087391", "면적": "2379", "공공편익시설정보": "주차장+무선 인터넷+유아시설(놀이방)+화장실", "지정일자": "2017-06-01", "수용인원수": "20", "주차가능수": "20", "관광지소개": "섬진강 기찻길따라 떠나는 하늘여행 내안의 버킷리스트를 오늘 완성하세요세계대회를 개최할 수 있는 규모의 전국 최대의 패러글라이딩 체험장입니다.남녀노소 누구나 스릴 넘치는 긴장과 재미로 평생 이야기 할 수 있는 재미만 가져가세요~고객님께서 원하시는 체험을 선택 하시기만 하면 아주 멋지고 스릴넘치는 내안의 버킷리스트와 함께 소중한 추억을 담아 드리겠습니다.", "관리기관전화번호": "061-363-6696", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(20, 4, 61, '관광지', '관광지', '곡성기차마을전통시장', '곡성기차마을전통시장은 곡성의 대표적인 전통시장으로 2009년 현재의 자리로 옮긴 곡성장이 곡성기차마을전통시장으로 거듭나면서 곡성사람들은 물론 곡성 기차마을을 찾는 관광객들이 들려가는 필수 코스로 자리 잡고 있다. 애초에는 3일에 끝나는 날짜에 여는 10일 장이었다가, 19세기 중반부터 지금까지 매3일과 8일에 장이 서는 오일장으로 바뀌었다고 한다.고려말 이곳에 곡성읍이 들어설때부터 곡성장이 열렸을 것으로 추정하는데 지금까지 무려 600년을 이어온 대단한 전통을 가진 장인 셈이다. 600년 전통으로 이어 내려온 곡성장의 정취와 인심은 곡성기차마을전통시장에 고스란히 남아 있다. 지금도 곡성장에 가면 깊은 산중에서 나는 능이버섯, 송이버섯, 귀한 산나물과 약초를 쉽게 발견할 수 있다. 곡성의 특산물인 멜론, 토란같은 품질 좋은 농산물을 저렴한 가격으로 구입할 수 있다.', '전남광주통합특별시 곡성군 곡성읍 곡성로 856', '전남광주통합특별시 곡성군 곡성읍 읍내리 208', 35.27976851, 127.2984461, '061-363-9002', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '43', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'c9d0521f6f9711dfc2029e15fca4aef459109a92fa8517ab546f345d4bada25a', '2026-08-08', '{"관광지명": "곡성기차마을전통시장", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 곡성읍 곡성로 856", "소재지지번주소": "전남광주통합특별시 곡성군 곡성읍 읍내리 208", "위도": "35.27976851", "경도": "127.2984461", "면적": "23342", "공공편익시설정보": "주차장", "지정일자": "1975-06-01", "수용인원수": "1000", "주차가능수": "43", "관광지소개": "곡성기차마을전통시장은 곡성의 대표적인 전통시장으로 2009년 현재의 자리로 옮긴 곡성장이 곡성기차마을전통시장으로 거듭나면서 곡성사람들은 물론 곡성 기차마을을 찾는 관광객들이 들려가는 필수 코스로 자리 잡고 있다. 애초에는 3일에 끝나는 날짜에 여는 10일 장이었다가, 19세기 중반부터 지금까지 매3일과 8일에 장이 서는 오일장으로 바뀌었다고 한다.고려말 이곳에 곡성읍이 들어설때부터 곡성장이 열렸을 것으로 추정하는데 지금까지 무려 600년을 이어온 대단한 전통을 가진 장인 셈이다. 600년 전통으로 이어 내려온 곡성장의 정취와 인심은 곡성기차마을전통시장에 고스란히 남아 있다. 지금도 곡성장에 가면 깊은 산중에서 나는 능이버섯, 송이버섯, 귀한 산나물과 약초를 쉽게 발견할 수 있다. 곡성의 특산물인 멜론, 토란같은 품질 좋은 농산물을 저렴한 가격으로 구입할 수 있다.", "관리기관전화번호": "061-363-9002", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(21, 4, 61, '관광지', '관광지', '곡성청소년야영장', '증기기관차 종착역인 가정역에 도착하면, 승객들은 으레 섬진강을 가로지르는 출렁다리를 건너가는데 그곳 섬진강변에 청소년 야영장이 자리 잡고 있다.청소년 야영장 설립 목적은 청소년들이 몸과 마음을 단련하고 호연지기를 기를 수 있도록 하는 종합 수련장 역할을 하는 것으로 수익성 보다는 공익을 우선으로 하는 리조트 시설이다.따라서 숙소와 식당, 강당 그리고 각종 체험 시설을 갖추고, 1박 2일 또는 2박 3일의 청소년 수련 프로그램 위주로 운영 된다. 그러나 가족을 비롯한 일반인에게도 야영장 시설을 제공한다. 우선 텐트 50동을 설치할 수 있는 야영장을 비롯하여 별도의 글램핑장이 마련되어 있고, 신청을 하면 가족단위 숙소도 이용할 수 있다. 뿐만 아니라 섬진강 레프팅, 섬진강 자전거 하이킹등 다양한 레져 활동도 지원한다. 참고로 청소년 야영장 옆에는 주야간에 천체를 관측할 수 있는 섬진강천문대를 운영하고 있다.', '전남광주통합특별시 곡성군 고달면 가정마을길 51', '전남광주통합특별시 곡성군 고달면 두가리 627-2', 35.22777786, 127.369723, '061-362-4186', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '300', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'f3fad2af80a4c72052ed48480801cefc29a7c77e4a788b67834fa075f7279bbb', '2026-08-08', '{"관광지명": "곡성청소년야영장", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 고달면 가정마을길 51", "소재지지번주소": "전남광주통합특별시 곡성군 고달면 두가리 627-2", "위도": "35.22777786", "경도": "127.369723", "면적": "1356", "공공편익시설정보": "화장실+샤워실+주차장", "지정일자": "2004-06-01", "수용인원수": "300", "주차가능수": "300", "관광지소개": "증기기관차 종착역인 가정역에 도착하면, 승객들은 으레 섬진강을 가로지르는 출렁다리를 건너가는데 그곳 섬진강변에 청소년 야영장이 자리 잡고 있다.청소년 야영장 설립 목적은 청소년들이 몸과 마음을 단련하고 호연지기를 기를 수 있도록 하는 종합 수련장 역할을 하는 것으로 수익성 보다는 공익을 우선으로 하는 리조트 시설이다.따라서 숙소와 식당, 강당 그리고 각종 체험 시설을 갖추고, 1박 2일 또는 2박 3일의 청소년 수련 프로그램 위주로 운영 된다. 그러나 가족을 비롯한 일반인에게도 야영장 시설을 제공한다. 우선 텐트 50동을 설치할 수 있는 야영장을 비롯하여 별도의 글램핑장이 마련되어 있고, 신청을 하면 가족단위 숙소도 이용할 수 있다. 뿐만 아니라 섬진강 레프팅, 섬진강 자전거 하이킹등 다양한 레져 활동도 지원한다. 참고로 청소년 야영장 옆에는 주야간에 천체를 관측할 수 있는 섬진강천문대를 운영하고 있다.", "관리기관전화번호": "061-362-4186", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(22, 4, 61, '관광지', '관광지', '심청한옥마을', '곡성군은 심청전의 원류 관음사연기설화가 있는 심청의 고장이다.KBS 역사스페셜 [역사추적 심청의 바닷길] 을 통해서 소개된 바와 같이 관음사 연기설화는 1700년전 장님 아버지를 둔 곡성의 효녀가 중국으로 건너가 진나라 황제의 황후가 되었는데, 아버지를 그리워하며 관음상을 만들어 고국으로 보내고, 아버지는 딸과 헤어지는 것이 슬퍼 흘린 눈물때문에 눈이 밝아졌다고 하는 내용이다.추론하여, 서기 300년 곡성땅은 철의 주산지였으며, 고대국가 형성의 중요한 자원이였던 철을 확보하기 위해 섬진강을 따라 중국 상인과 무역선이 드나드는 과정에서 곡성의 효녀가 중국 양자강 어귀의 보타섬으로 건너가 귀인이 되었다는 내용이다. 이에 따라 곡성군이 심청의 고장으로 떠오르면서 곡성군은 심청이 실천했던 아름다운 우리의 전통문화 효 사상을 계승 발전시키고자 전통한옥으로 된 심청이야기 마을을 조성하게 되었다.즉 효녀 심청의 이야기가 있는 마을을 만든 것이다. 심청이야기마을은 기와집과 초가집이 들어서 있는 전통 마을이다. 그래서 이곳에는 실제로 심청이살고 있을 것 같은 느낌을 준다. 마을의 이름을 ‘심청이야기마을’이라 정한 이유도 그것이다. 심청이야기마을은 섬진강을 끼고 달리는 17번 국도에서 들어간다. 돌로만들어진 이정표를 보고 증기기관차가 다니는 철길을 건너 산으로 향하는 길을 쭉 따라가면, 심청전을 상징하는 조형물들과 더불어 심청이야기마을이 모습을 드러낸다. 심청이야기마을은 억지로 산을 깍아서 조성한 것이 아니라, 원래 있었던 송정마을의 집터와 가옥의 원형을 최대한 살렸기 때문에, 전혀 이질감이 느껴지지 않는다. 이곳을 다녀간 사람들은 이구동성으로 곤방산 자락 울창한 숲속으로 연결되는 산책로를 최고로 친다. 그 길을 따라가면 곤방산 정상까지도 1시간 이내면 올라갈 수 있고, 여름밤엔 청정지역에서만 서식하는 반디불이도 어렵지 않게 만날 수 있다. 굳이 숙박을 하지않더라도 누구든지 부담없이 찾아와 마을을 둘러보며 초가집 돌담길을 배경으로 멋진 인증샷을 찍거나 곤방산 숲길을 산책할 수', '전남광주통합특별시 곡성군 오곡면 심청로 178', '전남광주통합특별시 곡성군 오곡면 송정리 274', 35.23063008, 127.3575205, '061-363-9910', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '8f5c349ecc18f2dc1aefb97bbd56949344b4384e20609adb7f984de8e6b087b5', '2026-08-08', '{"관광지명": "심청한옥마을", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 오곡면 심청로 178", "소재지지번주소": "전남광주통합특별시 곡성군 오곡면 송정리 274", "위도": "35.23063008", "경도": "127.3575205", "면적": "147603", "공공편익시설정보": "주차장+무선 인터넷+화장실", "지정일자": "2006-06-01", "수용인원수": "100", "주차가능수": "10", "관광지소개": "곡성군은 심청전의 원류 관음사연기설화가 있는 심청의 고장이다.KBS 역사스페셜 [역사추적 심청의 바닷길] 을 통해서 소개된 바와 같이 관음사 연기설화는 1700년전 장님 아버지를 둔 곡성의 효녀가 중국으로 건너가 진나라 황제의 황후가 되었는데, 아버지를 그리워하며 관음상을 만들어 고국으로 보내고, 아버지는 딸과 헤어지는 것이 슬퍼 흘린 눈물때문에 눈이 밝아졌다고 하는 내용이다.추론하여, 서기 300년 곡성땅은 철의 주산지였으며, 고대국가 형성의 중요한 자원이였던 철을 확보하기 위해 섬진강을 따라 중국 상인과 무역선이 드나드는 과정에서 곡성의 효녀가 중국 양자강 어귀의 보타섬으로 건너가 귀인이 되었다는 내용이다. 이에 따라 곡성군이 심청의 고장으로 떠오르면서 곡성군은 심청이 실천했던 아름다운 우리의 전통문화 효 사상을 계승 발전시키고자 전통한옥으로 된 심청이야기 마을을 조성하게 되었다.즉 효녀 심청의 이야기가 있는 마을을 만든 것이다. 심청이야기마을은 기와집과 초가집이 들어서 있는 전통 마을이다. 그래서 이곳에는 실제로 심청이살고 있을 것 같은 느낌을 준다. 마을의 이름을 ‘심청이야기마을’이라 정한 이유도 그것이다. 심청이야기마을은 섬진강을 끼고 달리는 17번 국도에서 들어간다. 돌로만들어진 이정표를 보고 증기기관차가 다니는 철길을 건너 산으로 향하는 길을 쭉 따라가면, 심청전을 상징하는 조형물들과 더불어 심청이야기마을이 모습을 드러낸다. 심청이야기마을은 억지로 산을 깍아서 조성한 것이 아니라, 원래 있었던 송정마을의 집터와 가옥의 원형을 최대한 살렸기 때문에, 전혀 이질감이 느껴지지 않는다. 이곳을 다녀간 사람들은 이구동성으로 곤방산 자락 울창한 숲속으로 연결되는 산책로를 최고로 친다. 그 길을 따라가면 곤방산 정상까지도 1시간 이내면 올라갈 수 있고, 여름밤엔 청정지역에서만 서식하는 반디불이도 어렵지 않게 만날 수 있다. 굳이 숙박을 하지않더라도 누구든지 부담없이 찾아와 마을을 둘러보며 초가집 돌담길을 배경으로 멋진 인증샷을 찍거나 곤방산 숲길을 산책할 수", "관리기관전화번호": "061-363-9910", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(23, 4, 61, '관광지', '관광지', '심청골짝나라학교', '전남광주통합특별시교육청 대안학교 위탁교육기관인 심청골짝나라학교는 학교 부적응 학생이나 폭력 등의 문제를 일으킨 아이들에게 퇴학이나 전학 조치가 취해지던 예전과는 달리 아이들은 위탁 교육기관에서 일정 기간의 교육을 받은 후 원적학교로 복귀하게 됩니다.  심청골짝나라학교는 이러한 아이들을 무료 대안교육 하는 기관입니다. 비영리단체로 운영되며 학교 운영에 필요한 비용은 체험학습이나 수련활동, 수익사업,  교직원 연수 등 프로그램을 제공한 수익금으로 충당합니다.  이곳의 교사들 역시 변화하는 아이들을 지켜보는 기쁨만으로 7년째 봉사하고 있습니다. 진정한 ’대안교육’을 꿈꾸는 사람들이 모인 학교입니다. 현재 다양한 교육프로그램을 제공하고 있습니다.', '전남광주통합특별시 곡성군 석곡면 방주마천목길 107', '전남광주통합특별시 곡성군 석곡면 방송리 590-1', 35.17183675, 127.2580116, '061-363-4224', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, 'bb222846ae4be714df12371f449a021f113c383b041344bb22fe0259fa212ef8', '2026-08-08', '{"관광지명": "심청골짝나라학교", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 석곡면 방주마천목길 107", "소재지지번주소": "전남광주통합특별시 곡성군 석곡면 방송리 590-1", "위도": "35.17183675", "경도": "127.2580116", "면적": "11391", "공공편익시설정보": "주차장", "지정일자": "2021-09-01", "수용인원수": "140", "주차가능수": "7", "관광지소개": "전남광주통합특별시교육청 대안학교 위탁교육기관인 심청골짝나라학교는 학교 부적응 학생이나 폭력 등의 문제를 일으킨 아이들에게 퇴학이나 전학 조치가 취해지던 예전과는 달리 아이들은 위탁 교육기관에서 일정 기간의 교육을 받은 후 원적학교로 복귀하게 됩니다.  심청골짝나라학교는 이러한 아이들을 무료 대안교육 하는 기관입니다. 비영리단체로 운영되며 학교 운영에 필요한 비용은 체험학습이나 수련활동, 수익사업,  교직원 연수 등 프로그램을 제공한 수익금으로 충당합니다.  이곳의 교사들 역시 변화하는 아이들을 지켜보는 기쁨만으로 7년째 봉사하고 있습니다. 진정한 ’대안교육’을 꿈꾸는 사람들이 모인 학교입니다. 현재 다양한 교육프로그램을 제공하고 있습니다.", "관리기관전화번호": "061-363-4224", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(24, 4, 61, '관광지', '관광지', '심청효문화센터', '곡성에서는 심청의 본고장이라는 자부심으로 만행의 근본이라 일컬어지는 효(孝) 정신을 널리 전파하기 위해서 매년 심청축제를 여는 등 다양한 노력을 기울이고 있다. ’효’는 이제 곡성을 상징하는 대표 키워드나 다름없다.따라서, 곡성에는 심청이 들어가는 명칭이 많은데, 그중 하나가 심청효문화센터다. 심청효문화센터는 곡성스러운 청정하고 조용한 분위기가 물씬 풍기는 시골마을 한켠에 자리 잡고 있다. 곡성 심청의 근원지인 관음사와 연계하여 심청의 효문화를 새롭게 조명하고 현대적인 효의 위상과 의미를 재정립하여 그 중요성을 인식하게 할 수 있는 교육의 장으로 활용하고자 체험공간과 숙소동을 갖추고 운영하고 있다. 한꺼번에 100여명을 수용할 수 있는 숙박시설과, 세미나실과 잔디 운동장, 야외취사장, 음향설비 등을 갖추고 있어 학생들의 현장학습, 기업연수, 대학생 M/T장소로 활용되고 있다. 아울러 심청의 효 문화를 알리기 위한 전시실과 더불어 ’효’ 체험 프로그램을 운영하고 있어, 가족단위의 발걸음도 꾸준히 이어진다.또한 인근에 조성된 심청공원도 꼭 들러볼 만한 곳이다. 이곳엔 심청전의 배역 인물을 묘사하는 장승 23기가 세워져 있다.', '전남광주통합특별시 곡성군 오산면 오산로 254-4', '전남광주통합특별시 곡성군 오산면 선세리 702', 35.20836622, 127.1288481, '061-363-4041', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '25', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '9257e66b23b33bfe333274ff9af95fdb231e58d66891ff726c963f086b427686', '2026-08-08', '{"관광지명": "심청효문화센터", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 오산면 오산로 254-4", "소재지지번주소": "전남광주통합특별시 곡성군 오산면 선세리 702", "위도": "35.20836622", "경도": "127.1288481", "면적": "2151", "공공편익시설정보": "주차장", "지정일자": "2018-08-01", "수용인원수": "200", "주차가능수": "25", "관광지소개": "곡성에서는 심청의 본고장이라는 자부심으로 만행의 근본이라 일컬어지는 효(孝) 정신을 널리 전파하기 위해서 매년 심청축제를 여는 등 다양한 노력을 기울이고 있다. ’효’는 이제 곡성을 상징하는 대표 키워드나 다름없다.따라서, 곡성에는 심청이 들어가는 명칭이 많은데, 그중 하나가 심청효문화센터다. 심청효문화센터는 곡성스러운 청정하고 조용한 분위기가 물씬 풍기는 시골마을 한켠에 자리 잡고 있다. 곡성 심청의 근원지인 관음사와 연계하여 심청의 효문화를 새롭게 조명하고 현대적인 효의 위상과 의미를 재정립하여 그 중요성을 인식하게 할 수 있는 교육의 장으로 활용하고자 체험공간과 숙소동을 갖추고 운영하고 있다. 한꺼번에 100여명을 수용할 수 있는 숙박시설과, 세미나실과 잔디 운동장, 야외취사장, 음향설비 등을 갖추고 있어 학생들의 현장학습, 기업연수, 대학생 M/T장소로 활용되고 있다. 아울러 심청의 효 문화를 알리기 위한 전시실과 더불어 ’효’ 체험 프로그램을 운영하고 있어, 가족단위의 발걸음도 꾸준히 이어진다.또한 인근에 조성된 심청공원도 꼭 들러볼 만한 곳이다. 이곳엔 심청전의 배역 인물을 묘사하는 장승 23기가 세워져 있다.", "관리기관전화번호": "061-363-4041", "관리기관명": "전남광주통합특별시 곡성군", "데이터기준일자": "2026-08-08", "제공기관코드": "5835000", "제공기관명": "전남광주통합특별시 곡성군"}', '2026-10-12 07:34:00'),
(25, 4, 61, '관광지', '관광지', '곡성생태체험관', '맑고 푸른 섬진강변의 수려한 자연경관을 배경으로 한 현장 체험 위주의 전인 교육장으로 환경과 자연생태의 중요성을 직접 체험하게 하여 그 소중함을 일깨우고 나아가 자연 환경보존을 실천하도록 하는데 목적이 있다.오랜 동안의 연구와 경험을 바탕으로 한 프로그램 운영으로 우리의 소중한 아이들이 즐겁게 뛰놀며 체험할 수 있고, 어른들의 지난 시절을 아름답게 추억할 수 있는 공간이다. 또한 초가집에서 잠을 자고 뛰어 놀 수 있는 놀이 마당과 창포머리감기, 고구마 구워먹기, 캠프파이어 등 방학기간 중 운영되는 환경캠프에도 많은 체험자가 참여하는 등 인기가 대단하다. 수려한 풍광을 자랑하는 곡성 옥과 설산자락, 폐교된 옛 옥수초등학교 부지에 자리 잡은 곡성생태체험관은 징검다리, 야생화 화단이 갖춰져 있어 청정 그대로의 자연과 접할 수 있다. 그리고 맘껏 뛰어놀 수 있는 널찍한 잔디 운동장과 야외무대도 마음을 사로잡는다.아련한 추억을 떠올리게 하는 옛날 초등학교 교실들은 각각 그릇을 직접 구어서 빚어볼 수 있는 도예체험관, 야생초나 야생화를 이용하여 옷감에 물을 들이는 천연염색체험관, 볏짚으로 각종 공예품을 만들어보는 짚풀 공예관 등으로 구성되어 있다. 그래서 어린이뿐만 아니라 어른들에게도 타임머신을 타고 동심의 세계로 돌아가게 해주는 곳이 곡성생태체험관이다. 가족단위 프로그램 참가신청도 가능하다.특히 방학기간에는 환경캠프를 운영 하는데, 생태체험관 기본 프로그램외에도 창포머리감기나, 고구마 구워먹기, 캠프파이어 등을 즐기며 자연과 보다 진한 교감을 맛보고 귀중한 추억도 만들 수 있다. 아울러, 함께 있는 합강투어텔에서는 숙박과 식사를 동시에 해결할 수 있어 매우 편리하다.', '전남광주통합특별시 곡성군 옥과면 월파로 295', '전남광주통합특별시 곡성군 옥과면 합강리 499-1', 35.31719414, 127.1699834, '061-363-2999', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '15', NULL, '전남광주통합특별시 곡성군', NULL, NULL, 1, '8cec4afcc5d91ea040019def09a8c9001ffde3cf697cacbc83fa8070865b9a10', '2026-08-08', '{"관광지명": "곡성생태체험관", "관광지구분": "관광지", "소재지도로명주소": "전남광주통합특별시 곡성군 옥과면 월파로 295", "소재지지번주소": "전남광주통합특별시 곡성군 옥과면 합강리 499-1", "위도": "35.31719414", "경도": "127.1699834", "면적": "314", "공공편익시설정보": "주차장+화장실+운동기구", "지정일자": "2002-06-01", "수용인원수": "100", "주차가능수": "15", "관광지소개": "맑고 푸른 섬진강변의 수려한 자연경관을 배경으로 한 현장 체험 위주의 전인 교육장으로 환경과 자연생태의 중요성을 직접 체험하게 하여 그 소중함을 일깨우고 나아가 자연 환경보존을 실천하도록 하는데 목적이 있다.오랜 동안의 연구와 경험을 바탕으로 한 프로그램 운영으로 우리의 소중한 아이들이 즐겁게 뛰놀며 체험할 수 있고, 어른들의 지난 시절을 아름답게 추억할 수 있는 공간이다. 또한 초가집에서 잠을 자고 뛰어 놀 수 있는 놀이 마당과 창포머리감기, 고구마 구워먹기, 캠프파이어 등 방학기간 중 운영되는 환경캠프에도 많은 체험자가 참여하는 등 인기가 대단하다. 수려한 풍광을 자랑하는 곡성 옥과 설산자락, 폐교된 옛 옥수초등학교 부지에 자리 잡은 곡성생태체험관은 징검다리, 야생화 화단이 갖춰져 있어 청정 그대로의 자연과 접할 수 있다. 그리고 맘껏 뛰어놀 수 있는 널찍한 잔디 운동장과 야외무대도 마음을 사로잡는다.아련한 추억을 떠올리게 하는 옛날 초등학교 교실들은 각각 그릇을 직접 구어서 빚어볼 수 있는 도예체험관, 야생초나 야생화를 이용하여 옷감에 물을 들이는 천연염색체험관, 볏짚으로 각종 공예품을 만들어보는 짚풀 공예관 등으로 구성되어 있다. 그래서 어린