(56, 9, 136, '관광지', '관광지', '에코리움', '생태학습관인 에코리움은 오산천 등의 전경을 내다볼 수 있는 전망대와 AR 체험관등으로 구성되어 있으며, 인근 하수종말처리장 위의 생태공원인 맑음터공원과 도심속에서 힐링과 여유를 만끽할 수 있는 캠핑장이 있다.', '경기도 오산시 오산천로 52', '경기도 오산시 오산동 750-1', 37.138241, 127.063546, '031-8036-6477', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '200', NULL, '경기도 오산시 환경사업소 도시공원과', NULL, NULL, 1, '23dc28f581c4036ee903340dca21107e0a1ebe1046242c2c99c873697467b27f', '2026-08-27', '{"관광지명": "에코리움", "관광지구분": "관광지", "소재지도로명주소": "경기도 오산시 오산천로 52", "소재지지번주소": "경기도 오산시 오산동 750-1", "위도": "37.138241", "경도": "127.063546", "면적": "1526", "공공편익시설정보": "주차장+화장실", "지정일자": "2011-05-05", "수용인원수": "630", "주차가능수": "200", "관광지소개": "생태학습관인 에코리움은 오산천 등의 전경을 내다볼 수 있는 전망대와 AR 체험관등으로 구성되어 있으며, 인근 하수종말처리장 위의 생태공원인 맑음터공원과 도심속에서 힐링과 여유를 만끽할 수 있는 캠핑장이 있다.", "관리기관전화번호": "031-8036-6477", "관리기관명": "경기도 오산시 환경사업소 도시공원과", "데이터기준일자": "2026-08-27", "제공기관코드": "4000000", "제공기관명": "경기도 오산시"}', '2026-10-12 07:34:00'),
(57, 9, 136, '관광지', '관광지', '고인돌공원', '우리나라 선사시대 문화유산인 고인돌9기가 분포하는 공원이다. 공원 내부에 산책로, 마을 정원과 멋스러운 야경이 문화유산과 잘 어우러진 장소로 조성되어 있어 산책코스가 인기가 많다.', '경기도 오산시 수목원로 449', '경기도 오산시 금암동 520', 37.174558, 127.048782, '031-8036-6466', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '147', NULL, '경기도 오산시 환경사업소 도시공원과', NULL, NULL, 1, 'eddc5b66abf215fea391a4f3aceb441f5c3f50d49a79426a52cce053b31ea09d', '2026-08-27', '{"관광지명": "고인돌공원", "관광지구분": "관광지", "소재지도로명주소": "경기도 오산시 수목원로 449", "소재지지번주소": "경기도 오산시 금암동 520", "위도": "37.174558", "경도": "127.048782", "면적": "94292", "공공편익시설정보": "공영주차장+화장실", "지정일자": "1988-12-02", "수용인원수": "1000", "주차가능수": "147", "관광지소개": "우리나라 선사시대 문화유산인 고인돌9기가 분포하는 공원이다. 공원 내부에 산책로, 마을 정원과 멋스러운 야경이 문화유산과 잘 어우러진 장소로 조성되어 있어 산책코스가 인기가 많다.", "관리기관전화번호": "031-8036-6466", "관리기관명": "경기도 오산시 환경사업소 도시공원과", "데이터기준일자": "2026-08-27", "제공기관코드": "4000000", "제공기관명": "경기도 오산시"}', '2026-10-12 07:34:00'),
(58, 9, 136, '관광지', '관광지', '화성궐리사', '궐리사는 오산의 영정을 모시고 공자의 기일과 탄일 석전대제를 올리고 매월 초파룻날과 보름날에 분향을 올리는 사당이다. 조선 중종때 공서린 선생이 후학양성을 하던 서재에서 시작되었으며 정조의 화성 신도시 건설과 함께 지금의 모습을 갖추게 되었다. 현재는 전통문화교육의 역할을 수행하면서 그 명맥을 이어가고 있다.', '경기도 오산시 매홀로 3', '경기도 오산시 궐동 147-1', 37.158993, 127.063692, '031-373-0151', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '14', NULL, '화성궐리사', NULL, NULL, 1, 'c7e798e07064b86051fe1d2c4a1aee7d8a57ceb96f1160d79d5574dcb2e0afe1', '2026-08-27', '{"관광지명": "화성궐리사", "관광지구분": "관광지", "소재지도로명주소": "경기도 오산시 매홀로 3", "소재지지번주소": "경기도 오산시 궐동 147-1", "위도": "37.158993", "경도": "127.063692", "면적": "8987", "공공편익시설정보": "공영주차장+화장실", "지정일자": "1994-04-20", "수용인원수": "150", "주차가능수": "14", "관광지소개": "궐리사는 오산의 영정을 모시고 공자의 기일과 탄일 석전대제를 올리고 매월 초파룻날과 보름날에 분향을 올리는 사당이다. 조선 중종때 공서린 선생이 후학양성을 하던 서재에서 시작되었으며 정조의 화성 신도시 건설과 함께 지금의 모습을 갖추게 되었다. 현재는 전통문화교육의 역할을 수행하면서 그 명맥을 이어가고 있다.", "관리기관전화번호": "031-373-0151", "관리기관명": "화성궐리사", "데이터기준일자": "2026-08-27", "제공기관코드": "4000000", "제공기관명": "경기도 오산시"}', '2026-10-12 07:34:00'),
(59, 9, 136, '관광지', '관광지', '오산 독산성과 세마대지', '삼국시대에 처음 쌓은 후 조선시대까지 운영되었던 긴 역사를 지닌 오산의 대표 유적이다. 성 내에는 장수의 지휘대인 세마대와 전통 사찰 보적사가 자리하고 있다. 산성 주변으로 음식문화거리와 넓은 주차장이 있으며, 오산오색둘레길 4코스인 독산숲길이 조성되어 있다.', '경기도 오산시 독산성로 269번길', '경기도 오산시 지곶동 155', 37.183334, 127.01982, '031-8036-7605', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '122', NULL, '경기도 오산시 문화예술과', NULL, NULL, 1, 'ca1a9aa06fafec45002b0c4432cca59e9bc6ef619ff6a2550603d1f2f8cebcb8', '2026-08-27', '{"관광지명": "오산 독산성과 세마대지", "관광지구분": "관광지", "소재지도로명주소": "경기도 오산시 독산성로 269번길", "소재지지번주소": "경기도 오산시 지곶동 155", "위도": "37.183334", "경도": "127.019820", "면적": "75254", "공공편익시설정보": "공영주차장+화장실", "지정일자": "1964-08-29", "수용인원수": "1000", "주차가능수": "122", "관광지소개": "삼국시대에 처음 쌓은 후 조선시대까지 운영되었던 긴 역사를 지닌 오산의 대표 유적이다. 성 내에는 장수의 지휘대인 세마대와 전통 사찰 보적사가 자리하고 있다. 산성 주변으로 음식문화거리와 넓은 주차장이 있으며, 오산오색둘레길 4코스인 독산숲길이 조성되어 있다.", "관리기관전화번호": "031-8036-7605", "관리기관명": "경기도 오산시 문화예술과", "데이터기준일자": "2026-08-27", "제공기관코드": "4000000", "제공기관명": "경기도 오산시"}', '2026-10-12 07:34:00'),
