(443, 10, 169, '관광지', '관광지', '궁산땅굴역사전시관', '궁산 땅굴은 태평양전쟁 말기 일제 강점기에 굴착된 곳으로, 무기나 탄약 등, 군수물 자를 저장하거나 김포 비행장을 감시하고, 공습 때에는 부대 본부로 사용하기 위한 곳이었다고 전해진다.', '서울특별시 강서구 양천로49길 102', NULL, 37.57266746, 126.8383649, '02-2600-7419', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '서울특별시 강서구청', NULL, NULL, 1, '6ebc5dece9af094927da27bb6e6447ed7e54766a936670ecc9229cdda742f682', '2026-03-18', '{"관광지명": "궁산땅굴역사전시관", "관광지구분": "관광지", "소재지도로명주소": "서울특별시 강서구 양천로49길 102", "위도": "37.57266746", "경도": "126.8383649", "면적": "758.11", "공공편익시설정보": "전기시설", "지정일자": "2018-05-11", "수용인원수": "15", "주차가능수": "0", "관광지소개": "궁산 땅굴은 태평양전쟁 말기 일제 강점기에 굴착된 곳으로, 무기나 탄약 등, 군수물 자를 저장하거나 김포 비행장을 감시하고, 공습 때에는 부대 본부로 사용하기 위한 곳이었다고 전해진다.", "관리기관전화번호": "02-2600-7419", "관리기관명": "서울특별시 강서구청", "데이터기준일자": "2026-03-18", "제공기관코드": "3150000", "제공기관명": "서울특별시 강서구"}', '2026-10-12 07:34:00'),
(444, 10, 169, '관광지', '관광지', '허준근린공원', '공원주위에는 서울 기념물 제11호인 허가바위가 있고 공원내에는 전설이 깃든 광주바위와 허준 선생이 앉아서 병자를 진료하는 인자한 모습의 동상 그리고 호수 정자 어린이 놀이 시설이 있으며 인근 주민들의 휴식공간으로 이용되고 있다.', '서울특별시 강서구 허준로5길 42', NULL, 37.56759867, 126.8537291, '02-2600-4196', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '서울특별시 강서구청', NULL, NULL, 1, '5f97b35520b8ce10bf5246567094b584ef32d79e977969bfdf74f4c8c92bafb1', '2026-03-18', '{"관광지명": "허준근린공원", "관광지구분": "관광지", "소재지도로명주소": "서울특별시 강서구 허준로5길 42", "위도": "37.56759867", "경도": "126.8537291", "면적": "29843", "공공편익시설정보": "화장실+관리사무실", "지정일자": "1993-10-31", "수용인원수": "20000", "주차가능수": "0", "관광지소개": "공원주위에는 서울 기념물 제11호인 허가바위가 있고 공원내에는 전설이 깃든 광주바위와 허준 선생이 앉아서 병자를 진료하는 인자한 모습의 동상 그리고 호수 정자 어린이 놀이 시설이 있으며 인근 주민들의 휴식공간으로 이용되고 있다.", "관리기관전화번호": "02-2600-4196", "관리기관명": "서울특별시 강서구청", "데이터기준일자": "2026-03-18", "제공기관코드": "3150000", "제공기관명": "서울특별시 강서구"}', '2026-10-12 07:34:00'),
