(453, 2, 23, '관광지', '관광지', '창원과학체험관', '미래 과학자의 소중한 꿈을 키워 나갈 수 있도록 자라나는 꿈나무들에게 과학을 쉽고 재미있게 즐기면서 배울 수 있는 과학체험관이다.', '경상남도 창원시 성산구 충혼로 72번길 16', NULL, 35.230268, 128.6617774, '055-267-2676', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '99', NULL, '경상남도 창원시청', NULL, NULL, 1, '2e2915fe5aead2a90bfece845e8ac65cece731fadfa34885b7617c21838b690c', '2026-02-09', '{"관광지명": "창원과학체험관", "관광지구분": "관광지", "소재지도로명주소": "경상남도 창원시 성산구 충혼로 72번길 16", "위도": "35.230268", "경도": "128.6617774", "면적": "31565", "공공편익시설정보": "화장실+주차장", "지정일자": "2010-01-05", "수용인원수": "250", "주차가능수": "99", "관광지소개": "미래 과학자의 소중한 꿈을 키워 나갈 수 있도록 자라나는 꿈나무들에게 과학을 쉽고 재미있게 즐기면서 배울 수 있는 과학체험관이다.", "관리기관전화번호": "055-267-2676", "관리기관명": "경상남도 창원시청", "데이터기준일자": "2026-02-09", "제공기관코드": "5670000", "제공기관명": "경상남도 창원시"}', '2026-10-12 07:34:00'),
(454, 2, 23, '관광지', '관광지', '마금산온천', '마금산온천은 약알칼리성 수질로 평균 수온이 55℃ 이상을 유지하고 있으며, 나트륨, 철, 칼슘, 라듐 등 20여종의 광물질을 포함하고 있다. 운동욕장, 수영장, 노천탕 등 보양온천 시설을 갖추고 치료와 요양, 휴양이 가능하다.', '경상남도 창원시 의창구 북면 천주로 1167', NULL, 35.35464845, 128.6094168, '055-225-3641', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '910', NULL, '경상남도 창원시청', NULL, NULL, 1, '618185b6e7fc5ec809681f5242a53c6ae472a09a9ec7a1f80cba07326b20ebee', '2026-02-09', '{"관광지명": "마금산온천", "관광지구분": "관광지", "소재지도로명주소": "경상남도 창원시 의창구 북면 천주로 1167", "위도": "35.35464845", "경도": "128.6094168", "면적": "528000", "공공편익시설정보": "화장실+주차장+족욕장+쉼터", "지정일자": "2015-07-29", "수용인원수": "4110", "주차가능수": "910", "관광지소개": "마금산온천은 약알칼리성 수질로 평균 수온이 55℃ 이상을 유지하고 있으며, 나트륨, 철, 칼슘, 라듐 등 20여종의 광물질을 포함하고 있다. 운동욕장, 수영장, 노천탕 등 보양온천 시설을 갖추고 치료와 요양, 휴양이 가능하다.", "관리기관전화번호": "055-225-3641", "관리기관명": "경상남도 창원시청", "데이터기준일자": "2026-02-09", "제공기관코드": "5670000", "제공기관명": "경상남도 창원시"}', '2026-10-12 07:34:00'),
(455, 2, 23, '관광지', '관광지', '주남저수지', '해마다 찾아오는 수만 마리의 철새들과 텃새들의 서식지로 다양한 수생식물, 수서곤충 등을 만나볼 수 있으며 철새들의 자유로운 곡예비행을 생생하게 관찰할 수 있는 곳이다. 천연기념물 16여종과 환경부 멸종위기 10여종 등 다양한 철새들을 직접 볼 수 있다.', '경상남도 창원시 의창구 동읍 주남로 101번길 26', NULL, 35.30732964, 128.6779306, '055-225-2798', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '44', NULL, '경상남도 창원시청', NULL, NULL, 1, 'c172abd0124918b44d8d30eccc8061b34bba0e63590e23916b797f2a01655595', '2026-02-09', '{"관광지명": "주남저수지", "관광지구분": "관광지", "소재지도로명주소": "경상남도 창원시 의창구 동읍 주남로 101번길 26", "위도": "35.30732964", "경도": "128.6779306", "면적": "8980000", "공공편익시설정보": "관리사무소+화장실+주차장+전망대+생태학습관+람사르문화관", "지정일자": "2002-10-21", "수용인원수": "200", "주차가능수": "44", "관광지소개": "해마다 찾아오는 수만 마리의 철새들과 텃새들의 서식지로 다양한 수생식물, 수서곤충 등을 만나볼 수 있으며 철새들의 자유로운 곡예비행을 생생하게 관찰할 수 있는 곳이다. 천연기념물 16여종과 환경부 멸종위기 10여종 등 다양한 철새들을 직접 볼 수 있다.", "관리기관전화번호": "055-225-2798", "관리기관명": "경상남도 창원시청", "데이터기준일자": "2026-02-09", "제공기관코드": "5670000", "제공기관명": "경상남도 창원시"}', '2026-10-12 07:34:00'),
