(789, 4, 57, '관광지', '관광지', '순천만습지', '75㎢가 넘는 해수역, 22.6㎢의 갯벌면적, 5.4㎢에 달하는 거대한 갈대군락과 겨울이면 흑두루미, 재두루미, 노랑부리저어새, 큰고니, 검은머리물떼새 등 순천만에서 발견되는 철새는 총 230여종으로 우리나라 전체 조류의 절반가량이나 되며 2003년 습지 보호지역, 2006년 람사르협약 등록, 2008년 국가지정문화재 명승 제41호로 지정된 순천만은 농게, 칠게, 짱뚱어 등과 같은 갯벌 생물들이 한데 어우러져 살아가고 있음.', '전라남도 순천시 순천만길 513-25(대대동)', '전라남도 순천시 대대동 162-2', 34.88579701, 127.5092833, '061-749-6052', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '600', NULL, '전라남도 순천시청 순천만보전과', NULL, NULL, 1, '14073b8a410a838a52805a86ee089eceb32bfa48de0e98132b64fd6bb13e6202', '2024-11-19', '{"관광지명": "순천만습지", "관광지구분": "관광지", "소재지도로명주소": "전라남도 순천시 순천만길 513-25(대대동)", "소재지지번주소": "전라남도 순천시 대대동 162-2", "위도": "34.88579701", "경도": "127.5092833", "면적": "3015859", "공공편익시설정보": "순천만쉼터+ 공예·특산품관+ 안내소+유모차대여+양산대여", "운동및오락시설정보": "용산전망대+순천만갈대밭", "휴양및문화시설정보": "순천문학관+체험선+순천만역사관+자연생태관", "지정일자": "2008-06-16", "수용인원수": "1000", "주차가능수": "600", "관광지소개": "75㎢가 넘는 해수역, 22.6㎢의 갯벌면적, 5.4㎢에 달하는 거대한 갈대군락과 겨울이면 흑두루미, 재두루미, 노랑부리저어새, 큰고니, 검은머리물떼새 등 순천만에서 발견되는 철새는 총 230여종으로 우리나라 전체 조류의 절반가량이나 되며 2003년 습지 보호지역, 2006년 람사르협약 등록, 2008년 국가지정문화재 명승 제41호로 지정된 순천만은 농게, 칠게, 짱뚱어 등과 같은 갯벌 생물들이 한데 어우러져 살아가고 있음.", "관리기관전화번호": "061-749-6052", "관리기관명": "전라남도 순천시청 순천만보전과", "데이터기준일자": "2024-11-19", "제공기관코드": "5790000", "제공기관명": "전남광주통합특별시 순천시"}', '2026-10-12 07:34:00'),
(790, 10, 156, '관광지', '관광지', '남산&N서울타워', '남산서울타워는 효율적인 방송전파 송수신과 한국의 전통미를 살린 관광 전망시설의 기능을 겸비한 국내 최초의 종합전파 탑으로 방송문화와 관광산업의 미래를 위해 건립되었습니다. 세계 유명한 종합 탑들이 그 나라 또는 그 도시의 상징적인 존재가 된 것처럼 남산서울타워 역시 지난 40여 년간 대한민국의 대표적인 관광지이자 서울의 상징물 역할을 해왔습니다.', '서울특별시 용산구 남산공원길 105', '서울특별시 용산구 용산동2가 산1-3', 37.55112257, 126.9878678, '02-2199-7240', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '서울특별시 용산구청 문화진흥과', NULL, NULL, 1, '2eea35035d3a4591119038702b79af2eb595e627632a2ebce3b40ddb231274be', '2025-07-25', '{"관광지명": "남산&N서울타워", "관광지구분": "관광지", "소재지도로명주소": "서울특별시 용산구 남산공원길 105", "소재지지번주소": "서울특별시 용산구 용산동2가 산1-3", "위도": "37.55112257", "경도": "126.9878678", "면적": "8456", "공공편익시설정보": "화장실+주차장+관광안내소+수유실", "휴양및문화시설정보": "전망대", "접객시설정보": "푸드코트+카페", "지정일자": "1980-10-15", "수용인원수": "600", "주차가능수": "0", "관광지소개": "남산서울타워는 효율적인 방송전파 송수신과 한국의 전통미를 살린 관광 전망시설의 기능을 겸비한 국내 최초의 종합전파 탑으로 방송문화와 관광산업의 미래를 위해 건립되었습니다. 세계 유명한 종합 탑들이 그 나라 또는 그 도시의 상징적인 존재가 된 것처럼 남산서울타워 역시 지난 40여 년간 대한민국의 대표적인 관광지이자 서울의 상징물 역할을 해왔습니다.", "관리기관전화번호": "02-2199-7240", "관리기관명": "서울특별시 용산구청 문화진흥과", "데이터기준일자": "2025-07-25", "제공기관코드": "3020000", "제공기관명": "서울특별시 용산구"}', '2026-10-12 07:34:00'),
