(828, 4, 74, '관광지', '관광지', '완도수목원', '국내 유일의 난대수목원으로 3,801종의 수목유전자원을 보유하고 있다. 난대성 목,초본 등 희귀식물 770여종이 자생하고 있는데 아열대,온대 교차지의 다양한 식물이 분포하여 학술적 가치가 높은 수목원이다.', '전라남도 완도군 군외면 초평1길 156', NULL, 34.36065258, 126.6635321, '061-552-1544', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '100', NULL, '전라남도 산림연구원', NULL, NULL, 1, '52e4594b79447905d926d68403b391348e1142988d5a0ad48be8d323f687bd65', '2024-08-16', '{"관광지명": "완도수목원", "관광지구분": "관광지", "소재지도로명주소": "전라남도 완도군 군외면 초평1길 156", "위도": "34.36065258", "경도": "126.6635321", "면적": "2050", "공공편익시설정보": "화장실+주차장+관광안내소", "지정일자": "1998-09-01", "수용인원수": "1000", "주차가능수": "100", "관광지소개": "국내 유일의 난대수목원으로 3,801종의 수목유전자원을 보유하고 있다. 난대성 목,초본 등 희귀식물 770여종이 자생하고 있는데 아열대,온대 교차지의 다양한 식물이 분포하여 학술적 가치가 높은 수목원이다.", "관리기관전화번호": "061-552-1544", "관리기관명": "전라남도 산림연구원", "데이터기준일자": "2024-08-16", "제공기관코드": "5900000", "제공기관명": "전남광주통합특별시 완도군"}', '2026-10-12 07:34:00'),
(829, 4, 74, '관광지', '관광지', '해양생태전시관', '기존 장보고기념관, 장도 등 청해진 유적지의 기존 문화·관광 시설과 연계하여 방문하는 관광객과 주민들에게 볼거리, 체험거리 제공 및 해양생태에 대한 교육의 장을 마련하고 해양치유 산업의 중요성을 제공하는데 그 의의가 있다. 1층과 2층으로 나뉘어 각 실마다 저마다의 주제를 가지고 완도의 역사, 생태계 현황, 다양한 해양 체험활동 등을 학습하고 경험할 수 있다.', '전라남도 완도군 완도읍 청해진로 1459', NULL, 34.351532, 126.731489, '061-550-6944', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '100', NULL, '전라남도 완도군청 시설관리사업소', NULL, NULL, 1, '8d86421393d3beb7118a5bbd4c2751568655cb495250f60ec7de44e1a9258f1e', '2024-08-16', '{"관광지명": "해양생태전시관", "관광지구분": "관광지", "소재지도로명주소": "전라남도 완도군 완도읍 청해진로 1459", "위도": "34.351532", "경도": "126.731489", "면적": "1305", "공공편익시설정보": "화장실+주차장+관광안내소", "지정일자": "2018-08-08", "수용인원수": "1000", "주차가능수": "100", "관광지소개": "기존 장보고기념관, 장도 등 청해진 유적지의 기존 문화·관광 시설과 연계하여 방문하는 관광객과 주민들에게 볼거리, 체험거리 제공 및 해양생태에 대한 교육의 장을 마련하고 해양치유 산업의 중요성을 제공하는데 그 의의가 있다. 1층과 2층으로 나뉘어 각 실마다 저마다의 주제를 가지고 완도의 역사, 생태계 현황, 다양한 해양 체험활동 등을 학습하고 경험할 수 있다.", "관리기관전화번호": "061-550-6944", "관리기관명": "전라남도 완도군청 시설관리사업소", "데이터기준일자": "2024-08-16", "제공기관코드": "5900000", "제공기관명": "전남광주통합특별시 완도군"}', '2026-10-12 07:34:00'),
(830, 4, 74, '관광지', '관광지', '장보고기념관', '장보고대사의 도전정신과 기상을 엿볼 수 있는 다양한 자료와 유물이 전시되어 있다. 특히 전시실은 보고 듣고 만지는 체험형 입체 관람 시스템을 갖추고 있어 흥미로운 관람이 가능하다.', '전라남도 완도군 완도읍 청해진로 1455', NULL, 34.355097, 126.730164, '061-550-6945', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '100', NULL, '전라남도 완도군청 시설관리사업소', NULL, NULL, 1, '84e0e2e871b47f53942b0438cc2cff94b463b7c51cba1fa720c4100bdfe07fab', '2024-08-16', '{"관광지명": "장보고기념관", "관광지구분": "관광지", "소재지도로명주소": "전라남도 완도군 완도읍 청해진로 1455", "위도": "34.355097", "경도": "126.730164", "면적": "14472", "공공편익시설정보": "화장실+주차장+관광안내소", "지정일자": "2002-10-25", "수용인원수": "1000", "주차가능수": "100", "관광지소개": "장보고대사의 도전정신과 기상을 엿볼 수 있는 다양한 자료와 유물이 전시되어 있다. 특히 전시실은 보고 듣고 만지는 체험형 입체 관람 시스템을 갖추고 있어 흥미로운 관람이 가능하다.", "관리기관전화번호": "061-550-6945", "관리기관명": "전라남도 완도군청 시설관리사업소", "데이터기준일자": "2024-08-16", "제공기관코드": "5900000", "제공기관명": "전남광주통합특별시 완도군"}', '2026-10-12 07:34:00'),
