(848, 10, 156, '관광지', '관광지', '한강 나루터', '한강나루의 도승과 한강진의 별장은 한강단과 국가 정자인 제천정을 관리하는 한편, 제천정 아래 한강변에 설치한 수표석을 관찰하는 일까지 담당하였다.', NULL, '서울특별시 용산구 한남동 524-6', 37.530347, 127.007028, '02-2199-7240', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '서울특별시 용산구청 문화진흥과', NULL, NULL, 1, '0aa2c0264a78612b4f795757e6e9104dde308f00043fff99a9f47043cd4987b6', '2025-07-25', '{"관광지명": "한강 나루터", "관광지구분": "관광지", "소재지지번주소": "서울특별시 용산구 한남동 524-6", "위도": "37.530347", "경도": "127.007028", "면적": "998", "공공편익시설정보": "화장실", "지정일자": "1989-01-01", "수용인원수": "70", "주차가능수": "0", "관광지소개": "한강나루의 도승과 한강진의 별장은 한강단과 국가 정자인 제천정을 관리하는 한편, 제천정 아래 한강변에 설치한 수표석을 관찰하는 일까지 담당하였다.", "관리기관전화번호": "02-2199-7240", "관리기관명": "서울특별시 용산구청 문화진흥과", "데이터기준일자": "2025-07-25", "제공기관코드": "3020000", "제공기관명": "서울특별시 용산구"}', '2026-10-12 07:34:00'),
(849, 10, 156, '관광지', '관광지', '유관순 열사 추모비', '유관순 열사는 1920년 9월 28일 서대문형무소에서 모진 고문 끝에 순국한 후 현 용산구 이태원과 보광동 일대에 있던 이태원 공동묘지에 묻혔다. 이러한 역사적 사실을 근거로 열사의 숭고한 넋을 기리고자 이태원 부군당 옆에 유관순 열사 추모비를 세우고 이 일대를 이태원 부군당 역사공원으로 조성하였다.', '서울특별시 용산구 녹사평대로40다길 37', '서울특별시 용산구 이태원동 192', 37.53587802, 126.9897044, '02-2199-7240', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '서울특별시 용산구청 문화진흥과', NULL, NULL, 1, '853b1ec671569fa4bf5713a7ddb754eea2dccd85d87292091fae91e89040a9fa', '2025-07-25', '{"관광지명": "유관순 열사 추모비", "관광지구분": "관광지", "소재지도로명주소": "서울특별시 용산구 녹사평대로40다길 37", "소재지지번주소": "서울특별시 용산구 이태원동 192", "위도": "37.53587802", "경도": "126.9897044", "면적": "178", "공공편익시설정보": "관리사무소+쉼터", "지정일자": "2015-09-01", "수용인원수": "20", "주차가능수": "0", "관광지소개": "유관순 열사는 1920년 9월 28일 서대문형무소에서 모진 고문 끝에 순국한 후 현 용산구 이태원과 보광동 일대에 있던 이태원 공동묘지에 묻혔다. 이러한 역사적 사실을 근거로 열사의 숭고한 넋을 기리고자 이태원 부군당 옆에 유관순 열사 추모비를 세우고 이 일대를 이태원 부군당 역사공원으로 조성하였다.", "관리기관전화번호": "02-2199-7240", "관리기관명": "서울특별시 용산구청 문화진흥과", "데이터기준일자": "2025-07-25", "제공기관코드": "3020000", "제공기관명": "서울특별시 용산구"}', '2026-10-12 07:34:00'),
(850, 10, 156, '관광지', '관광지', '이태원 부군당', '부군당은 마을의 안녕과 복을 지켜주는 부군신을 모신 곳으로 서울의 대표적인 마을신앙이다. 당내 정면 중앙에는 부군할아버지와 부군할머니를, 좌우로 12점의 신상을 마을 수호신으로 모시고 매년 음력 4월 1일에 제례와 굿을 올리고, 음력 10월 1일은 제관만이 모여 제사를 지내며 마을의 액을 몰아내고 복을 불러들여 동네와 주민의 평안을 지켜주시기를 기원하고 있다.', '서울특별시 용산구 녹사평대로40다길 37', '서울특별시 용산구 이태원동 192', 37.53587802, 126.9897044, '02-2199-7240', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0', NULL, '서울특별시 용산구청 문화진흥과', NULL, NULL, 1, '8eebe95efb217b83176b154f5e1b83ce09bd8cee570a9a0baaf3dca2f67ad6a8', '2025-07-25', '{"관광지명": "이태원 부군당", "관광지구분": "관광지", "소재지도로명주소": "서울특별시 용산구 녹사평대로40다길 37", "소재지지번주소": "서울특별시 용산구 이태원동 192", "위도": "37.53587802", "경도": "126.9897044", "면적": "178", "공공편익시설정보": "관리사무소+쉼터", "지정일자": "1619-01-01", "수용인원수": "20", "주차가능수": "0", "관광지소개": "부군당은 마을의 안녕과 복을 지켜주는 부군신을 모신 곳으로 서울의 대표적인 마을신앙이다. 당내 정면 중앙에는 부군할아버지와 부군할머니를, 좌우로 12점의 신상을 마을 수호신으로 모시고 매년 음력 4월 1일에 제례와 굿을 올리고, 음력 10월 1일은 제관만이 모여 제사를 지내며 마을의 액을 몰아내고 복을 불러들여 동네와 주민의 평안을 지켜주시기를 기원하고 있다.", "관리기관전화번호": "02-2199-7240", "관리기관명": "서울특별시 용산구청 문화진흥과", "데이터기준일자": "2025-07-25", "제공기관코드": "3020000", "제공기관명": "서울특별시 용산구"}', '2026-10-12 07:34:00'),
(851, 10, 156, '관광지', '관광지', '천주교 순교성지 새남터 성당', '1950년 한국 천주교구는 지금의 장소를 순교성지로 지정하였다. 1981년에는 천주교 새남터 교회가 창설되고, 1987년에는 새남터 성당 건물과 기념관이 완공되어 대표적 천주교 순교지로 매김하였다.', '서울특별시 용산구 이촌로 80-8', '서울특별시 용산구 이촌동 199-1', 37.52512658, 126.9570717, '070-8672-0327', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '20', NULL, '새남터 성당', NULL, NULL, 1, '168e18ce93ec90860379327ca7dc7a842d3f0ea72d0715d2f251869447e03169', '2025-07-25', '{"관광지명": "천주교 순교성지 새남터 성당", "관광지구분": "관광지", "소재지도로명주소": "서울특별시 용산구 이촌로 80-8", "소재지지번주소": "서울특별시 용산구 이촌동 199-1", "위도": "37.52512658", "경도": "126.9570717", "면적": "3599", "공공편익시설정보": "화장실+관광안내소", "휴양및문화시설정보": "기념관", "지정일자": "1983-01-01", "수용인원수": "240", "주차가능수": "20", "관광지소개": "1950년 한국 천주교구는 지금의 장소를 순교성지로 지정하였다. 1981년에는 천주교 새남터 교회가 창설되고, 1987년에는 새남터 성당 건물과 기념관이 완공되어 대표적 천주교 순교지로 매김하였다.", "관리기관전화번호": "070-8672-0327", "관리기관명": "새남터 성당", "데이터기준일자": "2025-07-25", "제공기관코드": "3020000", "제공기관명": "서울특별시 용산구"}', '2026-10-12 07:34:00'),
